def max_sum(arr):
    n = len(arr)
    # Initialize two arrays to store the maximum sum of increasing and decreasing subsequences
    IS = [0] * n
    DS = [0] * n
    IS = arr[:]
    DS = arr[:]

    # Calculating the maximum sum of increasing subsequence
    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j] and IS[i] < IS[j] + arr[i]:
                IS[i] = IS[j] + arr[i]
    # Calculating the maximum sum of decreasing subsequence
